      },
      "defaultOpen": {
        "dataType": "select",
        "displayName": "Default Open Item",
        "defaultValue": "none",
        "options": ["none", "0", "1", "2", "3"],
        "group": "Content"
      },
      "iconPosition": {
        "dataType": "select",
        "displayName": "Icon Position",
        "defaultValue": "right",
