function Component({ config = {} }) {
  const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');
  const split = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);

  var uid = React.useMemo(function() { return 'la' + Math.random().toString(36).slice(2, 9); }, []);
  var p = uid;
  var reduced = React.useMemo(function() {
    return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }, []);

  var itemsRaw = config?.items || 'What makes Lumen different from other analytics tools?|Lumen pairs real-time event tracking with a drag-and-drop dashboard builder.,How does Lumen\'s pricing work?|Plans start at $29/month for up to 10,000 tracked events.,Is there a free trial?|Yes — every plan includes a 14-day free trial with full feature access.,What support options are available?|All plans include 24/7 email support with a 4-hour response guarantee.';
  var allowMultiple = bool(config?.allowMultiple, false);
  var defaultOpen = config?.defaultOpen || 'none';
  var iconPosition = config?.iconPosition || 'right';
  var iconStyle = config?.iconStyle || 'chevron';
  var transitionDuration = parseInt(config?.transitionDuration || '300');
  var effectiveDuration = reduced ? 0 : transitionDuration;

  var backgroundColor = config?.backgroundColor || '#FAFAF9';
  var itemBackground = config?.itemBackground || '#FFFFFF';
  var headerColor = config?.headerColor || '#1C1917';
  var contentColor = config?.contentColor || '#78716C';
  var iconColor = config?.iconColor || '#A8A29E';
  var iconActiveColor = config?.iconActiveColor || '#44403C';
  var borderColor = config?.borderColor || '#E7E5E4';
  var hoverBackground = config?.hoverBackground || '#F5F5F4';

  var headerFontSize = parseInt(config?.headerFontSize || '16');
  var contentFontSize = parseInt(config?.contentFontSize || '15');
  var headerFontWeight = config?.headerFontWeight || '500';
  var containerPadding = parseInt(config?.containerPadding || '24');
  var itemGap = parseInt(config?.itemGap || '8');

  var items = React.useMemo(function() {
    return split(itemsRaw).map(function(item, index) {
      var parts = item.split('|').map(function(s) { return s.trim(); });
      return { id: index, title: parts[0] || 'Item ' + (index + 1), content: parts[1] || '' };
    });
  }, [itemsRaw]);

  var getInitialOpen = function() {
    if (defaultOpen === 'none') return [];
    var index = parseInt(defaultOpen);
    return index < items.length ? [index] : [];
  };

  var _openItems = React.useState(getInitialOpen());
  var openItems = _openItems[0];
  var setOpenItems = _openItems[1];

  var _hoveredItem = React.useState(null);
  var hoveredItem = _hoveredItem[0];
  var setHoveredItem = _hoveredItem[1];

  var toggleItem = function(id) {
    if (allowMultiple) {
      setOpenItems(function(prev) {
        return prev.indexOf(id) !== -1
          ? prev.filter(function(i) { return i !== id; })
          : prev.concat([id]);
      });
    } else {
      setOpenItems(function(prev) {
        return prev.indexOf(id) !== -1 ? [] : [id];
      });
    }
  };

  var isOpen = function(id) {
    return openItems.indexOf(id) !== -1;
  };

  var renderIcon = function(open) {
    var iconProps = {
      width: 20,
      height: 20,
      viewBox: '0 0 20 20',
      fill: 'none',
      className: p + '-icon-svg',
      style: {
        transform: iconStyle === 'chevron'
          ? (open ? 'rotate(180deg)' : 'rotate(0deg)')
          : iconStyle === 'arrow'
            ? (open ? 'rotate(90deg)' : 'rotate(0deg)')
            : 'none'
      }
    };

    if (iconStyle === 'chevron') {
      return React.createElement('svg', iconProps,
        React.createElement('path', {
          d: 'M5 7.5L10 12.5L15 7.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      );
    }

    if (iconStyle === 'plus') {
      return React.createElement('svg', iconProps, [
        React.createElement('path', {
          key: 'v',
          d: 'M10 4V16',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          className: p + '-icon-svg',
          style: {
            opacity: open ? 0 : 1,
            transform: open ? 'rotate(90deg)' : 'rotate(0deg)',
            transformOrigin: 'center'
          }
        }),
        React.createElement('path', {
          key: 'h',
          d: 'M4 10H16',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round'
        })
      ]);
    }

    if (iconStyle === 'arrow') {
      return React.createElement('svg', iconProps,
        React.createElement('path', {
          d: 'M7.5 5L12.5 10L7.5 15',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      );
    }

    return null;
  };

  if (!items.length) {
    return React.createElement('div', {
      className: 'accordion',
      style: {
        backgroundColor: backgroundColor,
        padding: containerPadding + 'px',
        minHeight: '160px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: contentColor,
        fontSize: contentFontSize + 'px',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        textAlign: 'center'
      }
    }, 'Add accordion items to begin.');
  }

  return React.createElement('div', {
    className: 'accordion ' + p,
    style: {
      backgroundColor: backgroundColor,
      padding: containerPadding + 'px',
      minHeight: '200px'
    }
  }, [
    React.createElement('style', { key: 'style' }, `
      .${p}-header { transition: background-color ${effectiveDuration}ms ease; }
      .${p}-icon-wrap { transition: color ${effectiveDuration}ms ease; }
      .${p}-icon-svg { transition: transform ${effectiveDuration}ms ease, opacity ${effectiveDuration}ms ease; }
      .${p}-content { transition: grid-template-rows ${effectiveDuration}ms cubic-bezier(0.4, 0, 0.2, 1), opacity ${effectiveDuration}ms ease; }
      .${p}-header:focus-visible { outline: 2px solid ${iconActiveColor}; outline-offset: -2px; }
      @media (prefers-reduced-motion: reduce) {
        .${p} * { animation: none !important; transition: none !important; }
      }
    `),
    React.createElement('div', {
      key: 'list',
      style: {
        display: 'flex',
        flexDirection: 'column',
        gap: itemGap + 'px'
      }
    }, items.map(function(item) {
      var itemIsOpen = isOpen(item.id);
      var isHovered = hoveredItem === item.id;
      var headerId = p + '-header-' + item.id;
      var contentId = p + '-content-' + item.id;

      return React.createElement('div', {
        key: item.id,
        style: {
          backgroundColor: itemBackground,
          borderRadius: '8px',
          border: '1px solid ' + borderColor,
          overflow: 'hidden'
        }
      }, [
        React.createElement('button', {
          key: 'header',
          id: headerId,
          className: p + '-header',
          onClick: function() { toggleItem(item.id); },
          onMouseEnter: function() { setHoveredItem(item.id); },
          onMouseLeave: function() { setHoveredItem(null); },
          'aria-expanded': itemIsOpen,
          'aria-controls': contentId,
          style: {
            width: '100%',
            padding: '16px 20px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexDirection: iconPosition === 'left' ? 'row-reverse' : 'row',
            gap: '12px',
            background: isHovered ? hoverBackground : 'transparent',
            border: 'none',
            cursor: 'pointer',
            textAlign: 'left',
            borderRadius: 0
          }
        }, [
          React.createElement('span', {
            key: 'title',
            style: {
              fontSize: headerFontSize + 'px',
              fontWeight: headerFontWeight,
              color: headerColor,
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
              flex: 1
            }
          }, item.title),

          React.createElement('span', {
            key: 'icon',
            className: p + '-icon-wrap',
            style: {
              color: itemIsOpen ? iconActiveColor : iconColor,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0
            }
          }, renderIcon(itemIsOpen))
        ]),

        React.createElement('div', {
          key: 'content',
          id: contentId,
          role: 'region',
          'aria-labelledby': headerId,
          className: p + '-content',
          style: {
            display: 'grid',
            gridTemplateRows: itemIsOpen ? '1fr' : '0fr',
            opacity: itemIsOpen ? 1 : 0
          }
        }, React.createElement('div', {
          style: { overflow: 'hidden' }
        }, React.createElement('div', {
          style: {
            padding: '0 20px 20px 20px',
            borderTop: '1px solid ' + borderColor
          }
        }, React.createElement('p', {
          style: {
            fontSize: contentFontSize + 'px',
            color: contentColor,
            margin: 0,
            paddingTop: '16px',
            lineHeight: 1.7,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
          }
        }, item.content))))
      ]);
    }))
  ]);
}

