function Component({ config = {} }) {
  const [expandedIndex, setExpandedIndex] = React.useState(0);

  const reduced = React.useMemo(() => {
    return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }, []);

  const sectionTitle = config?.sectionTitle || 'Our Four Disciplines';
  const sectionSubtitle = config?.sectionSubtitle || 'Tap a card to see what each team actually delivers';

  const services = [
    {
      title: config?.service1Title || 'Strategic Consulting',
      description: config?.service1Description || 'We spend the first two weeks in your P&L and churn data, not in workshops.',
      number: config?.service1Number || '01'
    },
    {
      title: config?.service2Title || 'Digital Products',
      description: config?.service2Description || 'From a working prototype in week one to a shipped product in twelve weeks.',
      number: config?.service2Number || '02'
    },
    {
      title: config?.service3Title || 'Brand Identity',
      description: config?.service3Description || 'A full identity system delivered in six weeks: wordmark, type, color, voice guide.',
      number: config?.service3Number || '03'
    },
    {
      title: config?.service4Title || 'Growth Marketing',
      description: config?.service4Description || 'Paid, lifecycle, and SEO run off one shared dashboard.',
      number: config?.service4Number || '04'
    }
  ];

  const collapsedHeight = parseInt(config?.collapsedHeight || '80');
  const expandedHeight = parseInt(config?.expandedHeight || '240');
  const cardGap = parseInt(config?.cardGap || '8');
  const maxWidth = parseInt(config?.maxWidth || '700');

  const backgroundColor = config?.backgroundColor || '#0C0C0C';
  const cardBackgroundColor = config?.cardBackgroundColor || '#161616';
  const expandedCardBg = config?.expandedCardBg || '#1A1A1A';
  const titleColor = config?.titleColor || '#FFFFFF';
  const textColor = config?.textColor || '#A1A1AA';
  const numberColor = config?.numberColor || '#3F3F46';
  const accentColor = config?.accentColor || '#FFFFFF';
  const borderColor = config?.borderColor || '#27272A';

  const uid = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? 'cs' + React.useId().replace(/:/g, '')
      : 'cs' + Math.random().toString(36).slice(2, 9);
  }, []);
  const p = uid;

  const handleCardClick = (index) => {
    setExpandedIndex(expandedIndex === index ? -1 : index);
  };

  const getCardStyle = (index) => {
    const isExpanded = expandedIndex === index;

    return {
      width: '100%',
      height: isExpanded ? expandedHeight + 'px' : collapsedHeight + 'px',
      backgroundColor: isExpanded ? expandedCardBg : cardBackgroundColor,
      borderRadius: '12px',
      border: `1px solid ${isExpanded ? accentColor + '30' : borderColor}`,
      padding: '0 28px',
      cursor: 'pointer',
      overflow: 'hidden',
      transition: reduced ? 'none' : 'all 500ms cubic-bezier(0.34, 1.56, 0.64, 1)',
      position: 'relative'
    };
  };

  return (
    <div
      className={`accordion-stack-cards ${p}`}
      style={{
        backgroundColor,
        padding: '80px 40px',
        minHeight: '700px'
      }}
    >
      <style>{`
        .${p}-card:focus-visible { outline: 2px solid ${accentColor}; outline-offset: 2px; }
        .${p}-cta { transition: ${reduced ? 'none' : 'background-color 200ms ease-out, color 200ms ease-out, border-color 200ms ease-out'}; }
        .${p}-cta:hover, .${p}-cta:focus-visible {
          background-color: var(--${p}-accent) !important;
          color: var(--${p}-bg) !important;
          border-color: var(--${p}-accent) !important;
        }
        .${p}-cta:focus-visible { outline: 2px solid ${accentColor}; outline-offset: 2px; }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>

      {/* Section Header */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '0 auto 48px'
        }}
      >
        <h2
          style={{
            fontSize: '36px',
            fontWeight: '500',
            color: titleColor,
            margin: '0 0 12px 0',
            letterSpacing: '-0.02em'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '15px',
            color: textColor,
            margin: 0
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Accordion Cards */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '0 auto',
          display: 'flex',
          flexDirection: 'column',
          gap: cardGap + 'px'
        }}
      >
        {services.map((service, index) => {
          const isExpanded = expandedIndex === index;

          return (
            <div
              key={`${p}-accordion-${index}`}
              className={`${p}-card`}
              style={getCardStyle(index)}
              onClick={() => handleCardClick(index)}
              role="button"
              tabIndex={0}
              aria-expanded={isExpanded}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  handleCardClick(index);
                }
              }}
            >
              {/* Collapsed Header */}
              <div
                style={{
                  height: collapsedHeight + 'px',
                  display: 'flex',
                  alignItems: 'center',
