                }}
              >
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '20px'
                  }}
                >
                  {/* Number */}
                  <span
                    style={{
                      fontSize: '14px',
                      fontWeight: '500',
                      color: isExpanded ? accentColor : numberColor,
                      fontFamily: 'monospace',
                      transition: reduced ? 'none' : 'color 300ms ease-out'
                    }}
                  >
                    {service.number}
                  </span>

                  {/* Title */}
                  <h3
                    style={{
                      fontSize: '18px',
                      fontWeight: '500',
                      color: titleColor,
                      margin: 0
                    }}
                  >
                    {service.title}
                  </h3>
                </div>

                {/* Expand Icon */}
                <div
                  style={{
                    width: '32px',
                    height: '32px',
                    borderRadius: '50%',
                    backgroundColor: isExpanded ? accentColor : borderColor,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    transition: reduced ? 'none' : 'all 300ms ease-out'
                  }}
                >
                  <span
                    style={{
                      color: isExpanded ? backgroundColor : textColor,
                      fontSize: '18px',
                      transform: `rotate(${isExpanded ? 45 : 0}deg)`,
                      transition: reduced ? 'none' : 'transform 300ms ease-out',
                      lineHeight: 1
                    }}
                  >
                    +
                  </span>
                </div>
              </div>

              {/* Expanded Content */}
              <div
                style={{
                  opacity: isExpanded ? 1 : 0,
                  transform: `translateY(${isExpanded ? 0 : -10}px)`,
                  transition: reduced ? 'none' : 'all 400ms ease-out',
                  paddingBottom: isExpanded ? '28px' : 0
                }}
              >
                <p
                  style={{
                    fontSize: '15px',
                    color: textColor,
                    margin: '0 0 24px 0',
                    lineHeight: '1.7',
                    paddingLeft: '54px'
                  }}
                >
                  {service.description}
                </p>

                {/* CTA Button */}
                <div
                  style={{
                    paddingLeft: '54px'
                  }}
                >
                  <button
                    className={`${p}-cta`}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: 'transparent',
                      border: `1px solid ${borderColor}`,
                      borderRadius: '6px',
                      color: titleColor,
                      fontSize: '13px',
                      fontWeight: '500',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '8px',
                      [`--${p}-accent`]: accentColor,
                      [`--${p}-bg`]: backgroundColor
                    }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    Learn more
                    <span>→</span>
                  </button>
                </div>
              </div>

              {/* Progress Line */}
              <div
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  width: `${((index + 1) / services.length) * 100}%`,
                  height: '2px',
                  backgroundColor: accentColor,
                  opacity: isExpanded ? 0.3 : 0,
                  transition: reduced ? 'none' : 'opacity 300ms ease-out'
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Footer Note */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '40px auto 0',
          textAlign: 'center'
        }}
      >
        <p
          style={{
            fontSize: '13px',
            color: numberColor,
            margin: 0
          }}
        >
          {expandedIndex >= 0 ? `Viewing: ${services[expandedIndex]?.title}` : 'Select a service to learn more'}
        </p>
      </div>
    </div>
  );
}

