function Component({ config = {} }) {
  const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

  const [openItems, setOpenItems] = React.useState(new Set());
  const contentRefs = React.useRef([]);

  const uid = React.useMemo(() => 'fq' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const reduced = React.useMemo(() => {
    return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }, []);

  // Config values
  const itemsString = config?.items || "What is your return policy?|We offer a 30-day return policy on all unworn items, with free return shipping on orders over $75.; How long does shipping take?|Standard shipping takes 5-7 business days within the continental US.; Do you ship internationally?|Yes, we ship to over 50 countries, with delivery to the UK and EU typically taking 8-12 business days.";
  const allowMultiple = bool(config?.allowMultiple, false);
  const defaultOpen = config?.defaultOpen || "none";
  const animationDuration = reduced ? 0 : parseInt(config?.animationDuration || "300");
  const gap = parseInt(config?.gap || "12");
  const padding = parseInt(config?.padding || "20");
  const borderRadius = parseInt(config?.borderRadius || "8");
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const itemBackgroundColor = config?.itemBackgroundColor || "#F4F4F5";
  const itemActiveBackgroundColor = config?.itemActiveBackgroundColor || "#FAFAFA";
  const questionColor = config?.questionColor || "#18181B";
  const answerColor = config?.answerColor || "#71717A";
  const iconColor = config?.iconColor || "#18181B";
  const borderColor = config?.borderColor || "#E4E4E7";
  const fontSize = parseInt(config?.fontSize || 16);
  const fontWeight = config?.fontWeight || "500";

  // Parse FAQ items
  const items = React.useMemo(() => {
    return itemsString.split(';').map(item => {
      const [question, answer] = item.trim().split('|');
      return { question: question?.trim() || '', answer: answer?.trim() || '' };
    }).filter(item => item.question && item.answer);
  }, [itemsString]);

  // Initialize default open
  React.useEffect(() => {
    if (defaultOpen !== "none") {
      const index = parseInt(defaultOpen);
      if (index >= 0 && index < items.length) {
        setOpenItems(new Set([index]));
      }
    }
  }, [defaultOpen, items.length]);

  const toggleItem = (index) => {
    setOpenItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(index)) {
        newSet.delete(index);
      } else {
        if (!allowMultiple) {
          newSet.clear();
        }
        newSet.add(index);
      }
      return newSet;
    });
  };

  if (!items.length) {
    return (
      <div className="faq-accordion" style={{ width: '100%', maxWidth: '800px', backgroundColor, padding: '24px', color: answerColor, fontSize: `${fontSize}px` }}>
        Add FAQ items to begin.
      </div>
    );
  }

  const containerStyle = {
    width: '100%',
    maxWidth: '800px',
    backgroundColor: backgroundColor,
    padding: '24px'
  };

  const itemsContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: `${gap}px`
  };

  const itemStyle = (isOpen) => ({
    backgroundColor: isOpen ? itemActiveBackgroundColor : itemBackgroundColor,
    border: `1px solid ${borderColor}`,
    borderRadius: `${borderRadius}px`,
    overflow: 'hidden',
    transition: `background-color ${animationDuration}ms ease`
  });

  const buttonStyle = {
    width: '100%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: '16px',
    padding: `${padding}px`,
    backgroundColor: 'transparent',
    border: 'none',
    cursor: 'pointer',
    textAlign: 'left'
  };

  const questionStyle = {
    flex: 1,
    fontSize: `${fontSize}px`,
    fontWeight: fontWeight,
    color: questionColor,
    lineHeight: '1.5'
  };

  const iconWrapperStyle = (isOpen) => ({
    flexShrink: 0,
    width: '24px',
    height: '24px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    transform: isOpen ? 'rotate(45deg)' : 'rotate(0deg)',
    transition: `transform ${animationDuration}ms ease`,
    color: iconColor
  });

  const contentWrapperStyle = (index, isOpen) => {
    const content = contentRefs.current[index];
    const height = content ? content.scrollHeight : 0;

    return {
      maxHeight: isOpen ? `${height}px` : '0px',
      overflow: 'hidden',
      transition: `max-height ${animationDuration}ms cubic-bezier(0.22, 1, 0.36, 1)`
    };
  };

  const answerStyle = {
    padding: `0 ${padding}px ${padding}px ${padding}px`,
    fontSize: `${fontSize * 0.9}px`,
    fontWeight: '400',
    color: answerColor,
    lineHeight: '1.6'
  };

  return (
    <div className={`faq-accordion ${p}`} style={containerStyle}>
      <style>{`
        .${p}-trigger:focus-visible { outline: 2px solid ${iconColor}; outline-offset: -2px; }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div style={itemsContainerStyle}>
        {items.map((item, index) => {
          const isOpen = openItems.has(index);

          return (
            <div key={index} style={itemStyle(isOpen)}>
              <button
                className={`${p}-trigger`}
                style={buttonStyle}
                onClick={() => toggleItem(index)}
                aria-expanded={isOpen}
                aria-controls={`${p}-answer-${index}`}
                id={`${p}-question-${index}`}
              >
                <div style={questionStyle}>{item.question}</div>
                <div style={iconWrapperStyle(isOpen)}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <line x1="12" y1="5" x2="12" y2="19" />
                    <line x1="5" y1="12" x2="19" y2="12" />
                  </svg>
                </div>
              </button>

              <div style={contentWrapperStyle(index, isOpen)}>
                <div
                  ref={el => contentRefs.current[index] = el}
                  id={`${p}-answer-${index}`}
                  style={answerStyle}
                  role="region"
                  aria-labelledby={`${p}-question-${index}`}
                >
                  {item.answer}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

