                style={{
                  backgroundColor: itemBackground,
                  border: `1px solid ${itemBorder}`,
                  borderRadius: '8px',
                  overflow: 'hidden'
                }}
              >
                {/* Question Button */}
                <button
                  className={`${p}-trigger`}
                  onClick={() => toggleItem(index)}
                  onKeyDown={(e) => handleKeyDown(e, index)}
                  aria-expanded={isOpen}
                  aria-controls={`accordion-content-${index}`}
                  id={`accordion-button-${index}`}
                  style={{
                    width: '100%',
                    padding: '1.5rem',
                    backgroundColor: 'transparent',
                    border: 'none',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '1rem',
                    cursor: 'pointer',
                    textAlign: 'left',
                    fontFamily: 'inherit',
                    transition: 'background-color 200ms ease-out'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.02)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = 'transparent';
                  }}
                >
                  <span style={{
                    fontSize: `${questionFontSize}px`,
                    fontWeight,
                    color: questionColor,
                    lineHeight: 1.4,
                    flex: 1
                  }}>
                    {item.question}
                  </span>
                  <span style={{
                    color: isOpen ? activeIconColor : iconColor,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    flexShrink: 0,
                    transition: 'color 200ms ease-out'
                  }}>
                    {getIcon(isOpen)}
                  </span>
                </button>

                {/* Answer Content */}
                <div
                  id={`accordion-content-${index}`}
                  role="region"
                  aria-labelledby={`accordion-button-${index}`}
                  ref={el => contentRefs.current[index] = el}
                  style={{
                    maxHeight: isOpen ? (contentRefs.current[index]?.scrollHeight || 'none') : '0',
                    overflow: 'hidden',
                    transition: prefersReducedMotion ? 'none' : `max-height ${animationDuration}ms ease-out`,
                    willChange: 'max-height'
                  }}
                >
                  <div style={{
                    padding: '0 1.5rem 1.5rem 1.5rem',
                    borderTop: `1px solid ${itemBorder}`,
                    opacity: isOpen ? 1 : 0,
                    transform: isOpen ? 'translateY(0)' : 'translateY(-10px)',
                    transition: prefersReducedMotion 
                      ? 'none' 
                      : `opacity ${animationDuration}ms ease-out, transform ${animationDuration}ms ease-out`
                  }}>
                    <p style={{
                      fontSize: `${answerFontSize}px`,
                      fontWeight: '400',
                      color: answerColor,
                      lineHeight: 1.7,
                      margin: '1rem 0 0 0'
                    }}>
                      {item.answer}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <style>{`
        .${p}-trigger:focus-visible { outline: 2px solid ${activeIconColor}; outline-offset: -2px; }
        @media (prefers-reduced-motion: reduce) {
          .accordion * {
            transition: none !important;
            animation: none !important;
          }
        }
      `}</style>
    </div>
  );
}

