                      transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out'
                    }}>
                      +
                    </span>
                  </button>

                  {/* Answer Content */}
                  <div style={{
                    maxHeight: isOpen ? '1000px' : '0',
                    overflow: 'hidden',
