                    transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
                    fontFamily
                  }}
                  onMouseEnter={(e) => {
                    if (!prefersReducedMotion) {
                      e.currentTarget.style.backgroundColor = hoverColor;
                    }
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = cardBackgroundColor;
                  }}
                >
                  Collapse All
                </button>
              </div>
            )}
          </div>
        )}

        {/* Accordion Items */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '12px'
        }}>
          {filteredItems.map((item, index) => {
            const isOpen = openItems.has(index);

            return (
              <div
                key={index}
                style={{
                  backgroundColor: cardBackgroundColor,
                  border: `1px solid ${borderColor}`,
                  borderRadius: '8px',
                  overflow: 'hidden',
                  opacity: prefersReducedMotion ? 1 : 0,
                  transform: prefersReducedMotion ? 'translateY(0)' : 'translateY(10px)',
                  animation: prefersReducedMotion ? 'none' : `${p}-itemAppear 400ms ease-out ${index * 50}ms forwards`
                }}
              >
                {/* Question Header */}
                <button
                  className={`${p}-trigger`}
                  onClick={() => toggleItem(index)}
                  aria-expanded={isOpen}
                  style={{
                    width: '100%',
                    padding: '20px',
                    border: 'none',
                    backgroundColor: 'transparent',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: '16px',
                    cursor: 'pointer',
                    textAlign: 'left',
                    transition: prefersReducedMotion ? 'none' : 'background-color 200ms ease-out',
                    fontFamily
                  }}
                  onMouseEnter={(e) => {
                    if (!prefersReducedMotion) {
                      e.currentTarget.style.backgroundColor = hoverColor;
                    }
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = 'transparent';
                  }}
                >
                  <span style={{
                    fontSize: `${questionSize}px`,
                    fontWeight: '500',
                    color: questionColor,
                    lineHeight: '1.5'
                  }}>
                    {item.question}
                  </span>

                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 20 20"
                    fill="none"
                    style={{
                      flexShrink: 0,
                      transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                      transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out'
                    }}
                  >
                    <path
                      d="M5 7.5l5 5 5-5"
                      stroke={iconColor}
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </button>

                {/* Answer Content */}
                <div
                  ref={el => contentRefs.current[index] = el}
                  style={{
                    maxHeight: isOpen ? (contentRefs.current[index]?.scrollHeight + 'px') : '0px',
                    opacity: prefersReducedMotion ? (isOpen ? 1 : 0) : undefined,
                    overflow: 'hidden',
                    transition: prefersReducedMotion ? 'opacity 200ms ease-out' : 'max-height 400ms cubic-bezier(0.22, 1, 0.36, 1), opacity 200ms ease-out'
                  }}
                >
                  <div style={{
                    padding: '0 20px 20px 20px',
                    fontSize: `${answerSize}px`,
                    color: answerColor,
                    lineHeight: '1.7'
                  }}>
                    {item.answer}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* No Results */}
        {filteredItems.length === 0 && (
          <div style={{
            textAlign: 'center',
            padding: '60px 20px',
            color: answerColor
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>🔍</div>
            <div style={{ fontSize: '18px', fontWeight: '500', marginBottom: '8px' }}>
              No questions found
            </div>
            <div style={{ fontSize: '14px' }}>
              Try adjusting your search term
            </div>
          </div>
        )}
      </div>

      <style>{`
        @keyframes ${p}-itemAppear {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .${p}-trigger:focus-visible { outline: 2px solid ${iconColor}; outline-offset: -2px; }
        .${p}-search:focus-visible { outline: 2px solid ${iconColor}; outline-offset: 2px; }
        .${p}-btn:focus-visible { outline: 2px solid ${iconColor}; outline-offset: 2px; }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
    </div>
  );
}

content-glassaccordion:
const MANIFEST = {
  "type": "Content.GlassAccordion",
  "description": "Glass and Apple Spotlight accordion with expand/collapse functionality",
  "editorElement": {
    "selector": ".glass-accordion",
    "displayName": "Glass Accordion",
    "archetype": "container",
    "data": {
      "preset": {
        "dataType": "select",
        "displayName": "Design Preset",
        "defaultValue": "glass",
        "options": ["glass", "apple-spotlight"],
        "group": "Content"
      },
      "isExpanded": {
        "dataType": "booleanValue",
        "displayName": "Start Expanded",
        "defaultValue": false,
        "group": "Content"
      },
      "ruleId": {
        "dataType": "text",
        "displayName": "Rule ID",
        "defaultValue": "A001",
        "group": "Content"
      },
      "ruleCategory": {
        "dataType": "text",
        "displayName": "Category",
        "defaultValue": "Layout",
        "group": "Content"
      },
      "ruleElement": {
        "dataType": "text",
        "displayName": "Element",
        "defaultValue": "Repeaters",
        "group": "Content"
      },
      "ruleStatus": {
        "dataType": "select",
        "displayName": "Status",
        "defaultValue": "Active",
        "options": ["Active", "Inactive", "Draft"],
        "group": "Content"
      },
      "parentContainer": {
        "dataType": "text",
        "displayName": "Parent Container",
        "defaultValue": "Section > Strip",
        "group": "Content"
      },
      "condition": {
        "dataType": "text",
        "displayName": "Condition",
        "defaultValue": "Width > 80% viewport",
        "group": "Content"
      },
      "action": {
        "dataType": "text",
        "displayName": "Action",
        "defaultValue": "Stack vertically",
        "group": "Content"
      },
      "outputWidth": {
        "dataType": "text",
        "displayName": "Output Width",
        "defaultValue": "100%",
        "group": "Content"
      },
      "outputHeight": {
        "dataType": "text",
        "displayName": "Output Height",
        "defaultValue": "auto",
        "group": "Content"
      },
      "primaryColor": {
        "dataType": "color",
        "displayName": "Primary/Accent Color",
        "defaultValue": "#007AFF",
        "group": "Colors"
      },
      "textPrimary": {
        "dataType": "color",
        "displayName": "Primary Text",
        "defaultValue": "#1A1A1A",
        "group": "Colors"
      },
      "textSecondary": {
        "dataType": "color",
        "displayName": "Secondary Text",
        "defaultValue": "#6B7280",
        "group": "Colors"
      },
      "successColor": {
        "dataType": "color",
        "displayName": "Success/Active Color",
        "defaultValue": "#22C55E",
        "group": "Colors"
      },
      "warningColor": {
        "dataType": "color",
        "displayName": "Warning/Draft Color",
        "defaultValue": "#F59E0B",
        "group": "Colors"
      },
      "errorColor": {
        "dataType": "color",
        "displayName": "Error/Inactive Color",
        "defaultValue": "#EF4444",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Base Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "padding": {
        "dataType": "select",
        "displayName": "Content Padding",
        "defaultValue": "16",
        "options": ["12", "16", "20", "24"],
        "group": "Layout"
      },
      "animationDuration": {
        "dataType": "select",
        "displayName": "Animation Duration",
        "defaultValue": "300",
        "options": ["200", "300", "400", "500"],
        "group": "Animation"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'gac' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const preset = config?.preset || 'glass';
  const startExpanded = config?.isExpanded || false;
  const ruleId = config?.ruleId || 'LO-114';
  const ruleCategory = config?.ruleCategory || 'Responsive Layout';
  const ruleElement = config?.ruleElement || 'Image Repeater Grid';
  const ruleStatus = config?.ruleStatus || 'Active';
  const parentContainer = config?.parentContainer || 'Section > Hero Strip';
  const condition = config?.condition || 'Viewport width > 1280px';
  const action = config?.action || 'Collapse to single column';
  const outputWidth = config?.outputWidth || '1280px';
  const outputHeight = config?.outputHeight || '640px';

  const primaryColor = config?.primaryColor || '#007AFF';
  const textPrimary = config?.textPrimary || '#1A1A1A';
  const textSecondary = config?.textSecondary || '#6B7280';
  const successColor = config?.successColor || '#22C55E';
  const warningColor = config?.warningColor || '#F59E0B';
  const errorColor = config?.errorColor || '#EF4444';

  const fontSize = parseInt(config?.fontSize || 14);
  const padding = parseInt(config?.padding || 16);
  const animationDuration = parseInt(config?.animationDuration || 300);

  const [isExpanded, setIsExpanded] = React.useState(startExpanded);
  const [isHovered, setIsHovered] = React.useState(false);
  const [contentHeight, setContentHeight] = React.useState(0);
  const contentRef = React.useRef(null);

  React.useEffect(() => {
    if (contentRef.current) {
      setContentHeight(contentRef.current.scrollHeight);
    }
  }, [isExpanded, parentContainer, condition, action, outputWidth, outputHeight]);

  const reduced = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );
  const prefersReducedMotion = reduced;

  const transition = prefersReducedMotion ? 'none' : `all ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`;

  const toggle = () => setIsExpanded((v) => !v);
  const onHeaderKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggle();
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'Active': return successColor;
      case 'Inactive': return errorColor;
      case 'Draft': return warningColor;
      default: return textSecondary;
    }
  };

  const steps = [
    { label: 'Parent Container', value: parentContainer },
    { label: 'Condition', value: condition },
    { label: 'Action', value: action },
  ];

  const ChevronIcon = ({ style }) => (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={style}
    >
      <polyline points="6,9 12,15 18,9" />
    </svg>
  );

  // ═══════════════════════════════════════════════════════════════
  // APPLE SPOTLIGHT PRESET
  // ═══════════════════════════════════════════════════════════════

  if (preset === 'apple-spotlight') {
    return (
      <div
        className={`glass-accordion ${p}`}
        style={{
          background: 'rgba(255,255,255,0.72)',
          backdropFilter: 'blur(40px) saturate(180%)',
          WebkitBackdropFilter: 'blur(40px) saturate(180%)',
          borderRadius: 12,
          border: '0.5px solid rgba(0,0,0,0.1)',
          boxShadow: '0 25px 50px rgba(0,0,0,0.15), 0 0 0 0.5px rgba(0,0,0,0.05)',
          overflow: 'hidden',
          fontFamily: '-apple-system, BlinkMacSystemFont, "SF Pro Display", system-ui, sans-serif',
        }}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <style>{`
          .${p}-head:focus-visible { outline: 2px solid ${primaryColor}; outline-offset: -2px; }
          @media (prefers-reduced-motion: reduce) {
            .${p} * { animation: none !important; transition: none !important; }
          }
        `}</style>
        {/* Outer Row (Always Visible) */}
        <div
          className={`${p}-head`}
          role="button"
          tabIndex={0}
          aria-expanded={isExpanded}
          onClick={toggle}
          onKeyDown={onHeaderKeyDown}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: padding,
            padding: `${padding * 0.875}px ${padding}px`,
            cursor: 'pointer',
            transition,
            borderRadius: 8,
            margin: 4,
            background: isHovered ? 'rgba(0,122,255,0.1)' : 'transparent',
          }}
        >
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{
              fontSize: fontSize + 1,
              fontWeight: '500',
              color: textPrimary,
              letterSpacing: '-0.01em',
            }}>
              {ruleElement}
            </div>
            <div style={{
              fontSize: fontSize - 1,
              color: textSecondary,
              marginTop: 2,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}>
              {ruleCategory} · {parentContainer}
            </div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <span style={{
              fontSize: fontSize - 2,
              color: textSecondary,
              background: 'rgba(0,0,0,0.05)',
              padding: '4px 10px',
              borderRadius: 6,
            }}>
              {ruleId}
            </span>
            <span style={{
              fontSize: fontSize - 1,
              color: getStatusColor(ruleStatus),
              fontWeight: '500',
            }}>
              {ruleStatus}
            </span>
            <ChevronIcon style={{
              width: 16,
              height: 16,
              transition,
              transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)',
              color: '#8E8E93',
            }} />
          </div>
        </div>

        {/* Inner Content (Expandable) */}
        <div style={{
          maxHeight: isExpanded ? contentHeight : 0,
          overflow: 'hidden',
          transition: prefersReducedMotion ? 'none' : `max-height ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
        }}>
          <div ref={contentRef} style={{ padding: `0 ${padding}px ${padding}px` }}>
            <div style={{
              background: 'rgba(0,0,0,0.03)',
              borderRadius: 8,
              padding: padding,
            }}>
              {steps.map((step, idx) => (
                <div
                  key={idx}
                  style={{
                    display: 'flex',
                    alignItems: 'baseline',
                    justifyContent: 'space-between',
                    gap: padding,
                    padding: `${padding * 0.5}px 0`,
                    borderBottom: idx < steps.length - 1 ? '0.5px solid rgba(0,0,0,0.06)' : 'none',
                  }}
                >
                  <span style={{ fontSize, color: textSecondary }}>{step.label}</span>
                  <span style={{ fontSize, color: textPrimary, textAlign: 'right' }}>{step.value}</span>
                </div>
              ))}
            </div>

            {/* Output Section */}
            <div style={{
              marginTop: padding,
              paddingTop: padding,
              borderTop: '0.5px solid rgba(0,0,0,0.1)',
              display: 'flex',
              gap: padding * 2,
            }}>
              <div>
                <div style={{ fontSize: fontSize - 2, color: '#8E8E93' }}>Width</div>
                <div style={{ fontSize: fontSize + 2, color: '#007AFF', fontWeight: '600' }}>{outputWidth}</div>
              </div>
              <div>
                <div style={{ fontSize: fontSize - 2, color: '#8E8E93' }}>Height</div>
                <div style={{ fontSize: fontSize + 2, color: '#007AFF', fontWeight: '600' }}>{outputHeight}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ═══════════════════════════════════════════════════════════════
  // GLASS PRESET
  // ═══════════════════════════════════════════════════════════════

  return (
    <div
      className={`glass-accordion ${p}`}
      style={{
        background: 'rgba(255,255,255,0.25)',
        backdropFilter: 'blur(20px) saturate(180%)',
        WebkitBackdropFilter: 'blur(20px) saturate(180%)',
        borderRadius: 16,
        border: '1px solid rgba(255,255,255,0.3)',
        boxShadow: isHovered
          ? '0 12px 40px rgba(0,0,0,0.15), inset 0 1px 0 rgba(255,255,255,0.5)'
          : '0 8px 32px rgba(0,0,0,0.1), inset 0 1px 0 rgba(255,255,255,0.4)',
        overflow: 'hidden',
        transition,
        fontFamily: '-apple-system, BlinkMacSystemFont, "SF Pro Display", system-ui, sans-serif',
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <style>{`
        .${p}-head:focus-visible { outline: 2px solid ${primaryColor}; outline-offset: -2px; }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      {/* Outer Row (Always Visible) */}
      <div
        className={`${p}-head`}
        role="button"
        tabIndex={0}
        aria-expanded={isExpanded}
        onClick={toggle}
        onKeyDown={onHeaderKeyDown}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: `${padding * 1.25}px ${padding * 1.5}px`,
          cursor: 'pointer',
          transition,
          background: isHovered ? 'rgba(255,255,255,0.15)' : 'transparent',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <span style={{
            fontSize: fontSize + 2,
            fontWeight: '600',
            color: textPrimary,
            letterSpacing: '-0.01em',
          }}>
            {ruleElement}
          </span>
          <span style={{ fontSize: fontSize - 1, color: textSecondary }}>
            {ruleCategory}
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: padding }}>
          <span style={{
            fontSize: fontSize - 2,
            color: textPrimary,
            background: 'rgba(255,255,255,0.4)',
            backdropFilter: 'blur(10px)',
            padding: '6px 12px',
            borderRadius: 20,
            border: '1px solid rgba(255,255,255,0.3)',
          }}>
            {ruleId}
          </span>
          <span style={{
            fontSize: fontSize - 1,
            color: getStatusColor(ruleStatus),
            fontWeight: '600',
          }}>
            {ruleStatus}
          </span>
          <ChevronIcon style={{
            width: 18,
            height: 18,
            transition,
            transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)',
            color: textSecondary,
          }} />
        </div>
      </div>

      {/* Inner Content (Expandable) */}
      <div style={{
        maxHeight: isExpanded ? contentHeight : 0,
        overflow: 'hidden',
        transition: prefersReducedMotion ? 'none' : `max-height ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
      }}>
        <div ref={contentRef} style={{ padding: `0 ${padding * 1.5}px ${padding * 1.5}px` }}>
          {/* Step Cards */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {steps.map((step, idx) => (
              <div
                key={idx}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: padding,
                  background: 'rgba(255,255,255,0.2)',
                  backdropFilter: 'blur(10px)',
                  borderRadius: 10,
                  border: '1px solid rgba(255,255,255,0.2)',
                }}
              >
                <span style={{ fontSize, color: textSecondary }}>{step.label}</span>
                <span style={{ fontSize, color: textPrimary, fontWeight: '500' }}>{step.value}</span>
              </div>
            ))}
          </div>

          {/* Output Section */}
          <div style={{
            marginTop: padding,
            padding: padding * 1.25,
            background: `${primaryColor}20`,
            backdropFilter: 'blur(10px)',
            borderRadius: 12,
            border: `1px solid ${primaryColor}40`,
            display: 'flex',
            justifyContent: 'space-around',
          }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{
                fontSize: fontSize - 2,
                color: textSecondary,
                textTransform: 'uppercase',
                letterSpacing: '0.05em',
                marginBottom: 4,
              }}>
                Width
              </div>
              <div style={{
                fontSize: fontSize + 8,
                color: primaryColor,
                fontWeight: '700',
                letterSpacing: '-0.02em',
              }}>
                {outputWidth}
              </div>
            </div>
            <div style={{ textAlign: 'center' }}>
              <div style={{
                fontSize: fontSize - 2,
                color: textSecondary,
                textTransform: 'uppercase',
                letterSpacing: '0.05em',
                marginBottom: 4,
              }}>
                Height
              </div>
              <div style={{
                fontSize: fontSize + 8,
                color: primaryColor,
                fontWeight: '700',
                letterSpacing: '-0.02em',
              }}>
                {outputHeight}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
